  "code": "def deprecated_base_class(new_class, message=None, category=ScrapyDeprecationWarning):
    class Metaclass(type):
        def __init__(cls, name, bases, clsdict):
            if new_class not in bases:
                bases = bases + (new_class,)
            super(Metaclass, cls).__init__(name, bases, clsdict)

        def __subclasscheck__(cls, subclass):
            return issubclass(subclass, new_class) or super(Metaclass, cls).__subclasscheck__(subclass)

        def __instancecheck__(cls, instance):
            return isinstance(instance, new_class) or super(Metaclass, cls).__instancecheck__(instance)

    if message is None:
        message = f"Subclassing {cls.__name__} is deprecated. Please inherit from {new_class.__name__} instead."

    return warn_when_subclassed(new_class, message, category)"
}

